    {
      "type": "intro",
      "lines": [
        { "host": "A", "text": "It's Friday, November 27th, and this is The AI Edge, presented by Epilogue." },
        { "host": "B", "text": "Epilogue ships systems that know what they know, show their work, and fail visibly instead of quietly. Epilogue works the way this briefing works, checking every claim against the primary source and leaving out whatever doesn't reconcile. More at epiloguelabs.com." },
        { "host": "A", "text": "I'm Maya." },
