input.command:
node -e "
const d=require('./data/2026-11-27.json');
let n=0; for(const s of d.sections) n+=s.items.length;
console.log('items:',n);
console.log('sections:',d.sections.map(s=>s.name+' ('+s.items.length+')').join(' | '));
const sl={}; for(const s of d.sections) for(const i of s.items) for(const x of (i.storylines||[])) sl[x]=(sl[x]||0)+1;
console.log('storylines:',JSON.stringify(sl));
const sw=d.summary.join(' ').split(/\s+/).length; console.log('summary words:',sw);
console.log('title words:',d.title.split(/\s+/).length);
"

